import { Component, input } from '@angular/core';

export type HrmContentPad = 'none' | 'sm' | 'md' | 'lg';

/** hrm-app-shell — bố cục ngoài cùng của app. Slot: [appSideNav] (trái, full cao), [appTopNav] (trên vùng phải),
 *  [appBanner] (dải thông báo dưới top nav), nội dung (ng-content mặc định = vùng page content).
 *  Tự bố cục theo slot có mặt:
 *    • chỉ [appSideNav]      → side nav trái + content phải.
 *    • chỉ [appTopNav]       → top nav trên + content dưới.
 *    • cả hai (side + top)   → side nav trái (full cao) + top nav trên vùng phải + content dưới bên phải.
 *  Slot trống tự ẩn (:empty). contentPad = padding vùng content.
 *  <hrm-app-shell><hrm-side-nav appSideNav .../><hrm-top-nav appTopNav .../><router-outlet/></hrm-app-shell> */
@Component({
  selector: 'hrm-app-shell',
  template: `
    <div class="shell">
      <div class="shell-side"><ng-content select="[appSideNav]" /></div>
      <div class="shell-main">
        <div class="shell-top"><ng-content select="[appTopNav]" /></div>
        <div class="shell-banner"><ng-content select="[appBanner]" /></div>
        <div class="shell-content" [class]="padClass()"><ng-content /></div>
      </div>
    </div>
  `,
  host: { class: 'hrm-app-shell' },
  styles: [`
:host { display: block; height: 100%; min-height: 0; }
.shell { display: flex; height: 100%; min-height: 0; background: var(--bg-app); }

.shell-side { flex: none; display: flex; }
.shell-side:empty { display: none; }
/* Side nav lồng trong shell → kéo cao full (footer ghim đáy hoạt động). */
.shell-side ::ng-deep .hrm-side-nav { display: flex; height: 100%; }
.shell-side ::ng-deep .sn { height: 100%; }

.shell-main { flex: 1; display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.shell-top { flex: none; }
.shell-top:empty { display: none; }
.shell-banner { flex: none; }
.shell-banner:empty { display: none; }

.shell-content { flex: 1; overflow: auto; min-height: 0; }
.shell-content.pad-sm { padding: 12px; }
.shell-content.pad-md { padding: 20px; }
.shell-content.pad-lg { padding: 32px; }
  `],
})
export class HrmAppShell {
  /** Padding vùng content. Mặc định md. */
  readonly contentPad = input<HrmContentPad>('md');
  protected padClass(): string {
    const p = this.contentPad();
    return p === 'none' ? '' : 'pad-' + p;
  }
}
